DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='flight_quote'; EXECUTE replace(definition,'public.flight_quote(','public.flight_quote_without_fobs('); FOR definition IN SELECT pg_get_functiondef(oid) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('sign_lease','purchase_aircraft') LOOP EXECUTE replace(definition,'PERFORM sync_lease_payments();','PERFORM process_due_obligations(); PERFORM assert_company_investment();'); END LOOP; SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='manage_lease'; definition:=replace(definition,'PERFORM sync_lease_payments();','PERFORM process_due_obligations();'); EXECUTE replace(definition,$s$ELSIF p_action='renew' THEN$s$,$s$ELSIF p_action='renew' THEN PERFORM assert_company_investment();$s$); SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='sync_lease_payments'; EXECUTE replace(definition,'FROM lease_contracts WHERE company_id=v_company.id ORDER BY starts_at,id FOR UPDATE',$s$FROM lease_contracts WHERE company_id=v_company.id AND EXISTS(SELECT 1 FROM fleet_aircraft fa WHERE fa.id=lease_contracts.aircraft_id AND fa.returned_at IS NULL AND fa.ownership='LEASED') ORDER BY starts_at,id FOR UPDATE$s$); END $$;
CREATE OR REPLACE FUNCTION public.flight_quote(p_aircraft uuid,p_destination text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; cid uuid; origin text; o company_fobs%ROWTYPE; d company_fobs%ROWTYPE; fd numeric:=0; hd_o numeric:=0; hd_d numeric:=0; md numeric:=0; fuel numeric; landing numeric; handling numeric; maintenance numeric; savings numeric; BEGIN q:=flight_quote_without_fobs(p_aircraft,p_destination); SELECT company_id,location_icao INTO cid,origin FROM fleet_aircraft WHERE id=p_aircraft AND company_id IN(SELECT id FROM companies WHERE user_id=auth.uid()); SELECT * INTO o FROM company_fobs WHERE company_id=cid AND airport_icao=origin AND closed_at IS NULL; SELECT * INTO d FROM company_fobs WHERE company_id=cid AND airport_icao=p_destination AND closed_at IS NULL; IF coalesce(o.has_fuel_contract,false) THEN fd:=economy_number('fob_fuel_discount'); END IF; IF coalesce(o.has_handling_desk,false) THEN hd_o:=economy_number('fob_handling_discount'); END IF; IF coalesce(d.has_handling_desk,false) THEN hd_d:=economy_number('fob_handling_discount'); END IF; IF coalesce(o.has_maintenance_bay,false) OR coalesce(d.has_maintenance_bay,false) THEN md:=economy_number('fob_maintenance_discount'); END IF; fuel:=round((q->>'fuel_cost')::numeric*(1-fd),2); landing:=round((q->>'landing_fee')::numeric*(1-hd_d),2); handling:=round((q->>'handling_fee')::numeric*(1-(hd_o+hd_d)/2),2); maintenance:=round((q->>'maintenance')::numeric*(1-md),2); savings:=(q->>'fuel_cost')::numeric+(q->>'landing_fee')::numeric+(q->>'handling_fee')::numeric+(q->>'maintenance')::numeric-fuel-landing-handling-maintenance; RETURN q||jsonb_build_object('fuel_cost',fuel,'landing_fee',landing,'handling_fee',handling,'maintenance',maintenance,'net',(q->>'revenue')::numeric-fuel-landing-handling-maintenance,'fob_discounts',jsonb_build_object('fuel',fd,'landing',hd_d,'handling_origin',hd_o,'handling_destination',hd_d,'maintenance',md,'savings',savings)); END $$;
REVOKE ALL ON FUNCTION public.flight_quote_without_fobs(uuid,text) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='company_daily_results'; EXECUTE replace(replace(definition,$s$'MAINTENANCE_RESERVE'))$s$,$s$'MAINTENANCE_RESERVE','FOB_UPKEEP'))$s$),'least(k.ends_at,now(),','least(k.ends_at,(SELECT coalesce(returned_at,k.ends_at) FROM fleet_aircraft WHERE id=k.aircraft_id),now(),'); SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='reset_airports_state'; EXECUTE replace(definition,'IF EXISTS(SELECT 1 FROM flights','LOCK TABLE public.flights IN SHARE ROW EXCLUSIVE MODE; IF EXISTS(SELECT 1 FROM flights'); END $$;